import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import {
    answerSummary,
    actionSummary,
    decisionOutcome,
    decisionResult,
    applyDecisionFrame,
    createDecisionLog,
    decisionRows,
    outcomeSummary,
    questionGroups,
} from '@/utils/decisionLog';

// Generated by tests/decisions/test_log_fixture.py from a real framework run, so
// these frames are the ones the websocket route sends.
const { scenarios } = JSON.parse(
    readFileSync(resolve('tests/unit/fixtures/decisionLifecycle.json')),
);

function play(name, { frames = scenarios[name].length } = {}) {
    const log = createDecisionLog();
    for (const frame of scenarios[name].slice(0, frames)) applyDecisionFrame(log, frame);
    return log;
}

function live(name) {
    const log = createDecisionLog();
    for (const frame of scenarios[name]) {
        if (frame.event !== 'snapshot') applyDecisionFrame(log, frame);
    }
    return log;
}

function until(name, predicate) {
    const index = scenarios[name].findIndex(predicate);
    expect(index).toBeGreaterThan(-1);
    return index + 1;
}

describe('rows read from the record alone', () => {
    it('renders the pinned row from the request and the template reason', () => {
        const [row] = decisionRows(play('below_threshold'));
        expect(decisionResult(row)).toBe('repeats · probability 0.74');
        expect(decisionOutcome(row).label).toBe('No action');
        expect(outcomeSummary(row.request.outcomes[0])).toBe('No action (below 0.80)');
        expect(row.status).toBe('completed');
    });

    it('summarizes the shipped policy\'s per-check thresholds from real framework frames', () => {
        const [row] = decisionRows(play('per_check_thresholds'));
        expect(outcomeSummary(row.request.outcomes[0])).toBe('No action (below thresholds 0.76, 0.91)');
        expect(row.request.outcomes[0].details.thresholds).toEqual({ s1_repetition: 0.91, s1_description_reuse: 0.91, s1_style: 0.76 });
        expect(decisionRows(live('per_check_thresholds'))).toEqual(decisionRows(play('per_check_thresholds')));
    });

    it('builds the same row from the live frames alone, without a snapshot', () => {
        expect(decisionRows(live('below_threshold'))).toEqual(
            decisionRows(play('below_threshold')),
        );
    });

    it('says the reason is unspecified when the template supplied none', () => {
        const [row] = decisionRows(play('no_reason'));
        expect(decisionOutcome(row).label).toBe('No action');
        expect(outcomeSummary(row.request.outcomes[0])).toBe('No action; reason unspecified');
    });

    it('keeps a boolean probability labelled as a probability', () => {
        const [row] = decisionRows(play('action_taken'));
        expect(decisionResult(row)).toBe('repeats · probability 0.93');
        expect(decisionResult(row)).not.toMatch(/confidence|severity/);
    });
});

describe('the two lifecycles stay apart', () => {
    it('accepts an action that starts after the model response completed', () => {
        const name = 'action_taken';
        const completed = until(name, frame => frame.entry?.status === 'completed');
        const [before] = decisionRows(play(name, { frames: completed }));
        expect(before.request.status).toBe('completed');
        expect(before.request.actions).toEqual([]);
        expect(before.status).toBe('active');
        expect(decisionResult(before)).toBe('repeats · probability 0.93');
        expect(decisionOutcome(before).label).toBe('In progress');

        const dispatched = until(name, frame => frame.entry?.actions?.[0]?.status === 'pending');
        const [pending] = decisionRows(play(name, { frames: dispatched }));
        expect(pending.id).toBe(before.id);
        expect(pending.status).toBe('active');
        expect(decisionOutcome(pending).label).toBe('In progress');
        expect(actionSummary(pending.actions[0])).toBe('Revision rewrite pending');

        const [done] = decisionRows(play(name));
        expect(done.id).toBe(before.id);
        expect(done.status).toBe('completed');
        expect(decisionOutcome(done).label).toBe('Revision rewrite completed');
        expect(actionSummary(done.actions[0])).toBe('Revision rewrite completed · 820 ms');
    });

    it('reports the model duration and the action duration separately', () => {
        const [row] = decisionRows(play('action_taken'));
        expect(row.request.elapsed_ms).toBe(140);
        expect(row.request.actions[0].elapsed_ms).toBe(820);
    });

    it('does not call an unassociated action this request\'s outcome', () => {
        const [row] = decisionRows(play('unassociated_action'));
        expect(row.request.actions).toEqual([]);
        expect(row.actions[0].unassociated).toBe(true);
        expect(actionSummary(row.actions[0])).toBe('Revision rewrite completed · 820 ms');
        expect(decisionOutcome(row).label).toBe('No action');
    });
});

describe('failures stay visible and stay apart', () => {
    it('separates a dispatched failure from a request that was never sent', () => {
        const [sent] = decisionRows(play('request_failed'));
        expect(sent.request.dispatched).toBe(true);
        expect(decisionOutcome(sent).label).toBe('Failed');
        expect(decisionResult(sent)).toBe('Talemate could not reach the provider');
        expect(sent.status).toBe('failed');

        const [unsent] = decisionRows(play('request_not_sent'));
        expect(unsent.request.dispatched).toBe(false);
        expect(decisionOutcome(unsent).label).toBe('Not sent');
        expect(decisionResult(unsent)).toBe('The decision model is off');
    });

    it('shows the continuation the feature fell back to', () => {
        const [row] = decisionRows(play('request_failed'));
        expect(actionSummary(row.actions[0])).toBe('Disabled path completed (decision unavailable) · 820 ms');
    });

    it('marks a cancelled request without inventing an outcome', () => {
        const [row] = decisionRows(play('cancelled'));
        expect(row.status).toBe('cancelled');
        expect(decisionOutcome(row).label).toBe('Cancelled');
        expect(decisionResult(row)).toBe('1 question');
    });

    it('carries no credential or authorization field into a row', () => {
        const rows = Object.keys(scenarios).flatMap(name => decisionRows(play(name)));
        const text = JSON.stringify(rows);
        expect(text).not.toMatch(/api_key|authorization|bearer/i);
    });
});

describe('overlapping invocations', () => {
    it('keeps each invocation\'s outcome on its own row', () => {
        const rows = decisionRows(play('concurrent'));
        expect(rows).toHaveLength(2);
        const [acted, refused] = rows;
        expect(decisionOutcome(acted).label).toBe('Revision rewrite completed');
        expect(decisionResult(acted)).toBe('repeats · probability 0.93');
        expect(decisionOutcome(refused).label).toBe('No action');
        expect(decisionResult(refused)).toBe('repeats · probability 0.74');
        expect(outcomeSummary(refused.request.outcomes[0])).toBe('No action (below 0.80)');
        expect(acted.invocation.id).not.toBe(refused.invocation.id);
    });

    it('orders the rows with the newest first', () => {
        const rows = decisionRows(play('concurrent'));
        expect(rows.map(row => row.num)).toEqual([2, 1]);
    });
});

describe('retention and clearing follow the backend', () => {
    it('drops exactly the entries the backend removed', () => {
        const log = play('retention');
        const removed = scenarios.retention.find(frame => frame.event === 'removed');
        expect(removed.request_ids).toEqual(['request-1']);
        expect(decisionRows(log).map(row => row.id)).toEqual(['request-3', 'request-2']);
    });

    it('keeps a completed model whose action is still pending through a clear', () => {
        const name = 'clear_keeps_a_pending_action';
        const cleared = until(name, frame => frame.event === 'removed');
        const rows = decisionRows(play(name, { frames: cleared }));
        expect(rows.map(row => row.id)).toEqual(['request-2']);
        expect(rows[0].request.status).toBe('completed');
        expect(rows[0].status).toBe('active');
        expect(decisionRows(play(name))[0].status).toBe('completed');
    });

    it('replaces the whole store when a new snapshot arrives', () => {
        const log = play('retention');
        applyDecisionFrame(log, scenarios.below_threshold.at(-1));
        expect(decisionRows(log).map(row => row.request.template_uid)).toEqual([
            'editor.below-threshold',
        ]);
    });
});

describe('a row that has more than one of anything', () => {
    it('keeps one request of several questions on one row', () => {
        const rows = decisionRows(play('question_types'));
        expect(rows).toHaveLength(1);
        expect(Object.keys(rows[0].request.questions)).toEqual(['repeats', 'tone', 'tension']);
        expect(decisionResult(rows[0])).toBe('3 questions');
        expect(decisionOutcome(rows[0]).label).toBe('No action');
    });

    it('drops a pruned sibling\'s action rather than calling it unassociated', () => {
        const log = play('two_asks_pruned');
        const [row] = decisionRows(log);
        expect(Object.keys(log.requests)).toEqual(['request-2']);
        expect(row.invocation.request_count).toBe(2);
        expect(row.invocation.actions).toHaveLength(1);
        expect(row.actions).toEqual([]);
        expect(decisionOutcome(row).label).toBe('No action');
    });

    it('leaves a sibling request\'s action on the row that named it', () => {
        const rows = decisionRows(play('two_asks'));
        expect(rows.map(row => row.id)).toEqual(['request-2', 'request-1']);
        const [sibling, named] = rows;
        expect(named.actions.map(action => action.id)).toEqual(['action-1']);
        expect(decisionOutcome(named).label).toBe('Revision rewrite completed');
        expect(actionSummary(named.actions[0])).toBe('Revision rewrite completed · 820 ms');
        expect(sibling.actions).toEqual([]);
        expect(decisionOutcome(sibling).label).toBe('No action');
        expect(sibling.status).toBe('completed');
    });
});

describe('explicit presentation metadata', () => {
    it('groups checks and reads the flagged IDs recorded by the shipped policy', () => {
        const [row] = decisionRows(play('readable_checks'));
        const groups = questionGroups(row.request);
        expect(groups).toHaveLength(3);
        expect(groups[0].questions.map(item => [item.id, item.flagged])).toEqual([
            ['s1_repetition', true], ['s2_repetition', false],
        ]);
        expect(groups[2].questions[1].flagged).toBe(false);
        expect(decisionResult(row)).toBe('Flagged s1 · 0.91 (threshold 0.91)');
        expect(decisionRows(live('readable_checks'))).toEqual([row]);
    });

    it('does not invent a verdict before the template records one', () => {
        const [row] = decisionRows(play('readable_checks'));
        const request = { ...row.request, outcomes: [] };
        const questions = questionGroups(request).flatMap(group => group.questions);
        expect(questions.every(item => item.flagged === null)).toBe(true);
        expect(decisionResult({ ...row, request })).not.toContain('flagged');
    });

    it('uses an explicit empty flagged list even when a probability reaches the threshold', () => {
        const [row] = decisionRows(play('readable_checks'));
        const request = {
            ...row.request,
            outcomes: [{ action: 'no_action', reason: 'below_thresholds', details: { flagged_question_ids: [] } }],
        };
        expect(questionGroups(request)[0].questions[0].flagged).toBe(false);
        expect(decisionResult({ ...row, request })).toBe('Nothing flagged · highest s1 · 0.91 (threshold 0.91)');
    });

    it('does not infer passage identity from a custom question name', () => {
        const [row] = decisionRows(play('readable_checks'));
        const original = row.request;
        const request = {
            ...original,
            questions: { custom_name: original.questions.s1_repetition },
            answers: { custom_name: original.answers.s1_repetition },
            presentation: { custom_name: original.presentation.s1_repetition },
        };
        expect(questionGroups(request)[0].questions[0].presentation.passage_text).toBe('She paid the clerk again.');
        expect(questionGroups({ ...request, presentation: {} })[0].questions[0].presentation).toBeUndefined();
    });
});

describe('an action that never ran, and one that broke', () => {
    it('shows a denied action as skipped and names the policy failure', () => {
        const [row] = decisionRows(play('action_denied'));
        expect(row.status).toBe('failed');
        expect(decisionOutcome(row).label).toBe('Failed');
        expect(row.request.policy_failure.code).toBe('action_denied');
        expect(row.actions.map(actionSummary)).toEqual([
            'Revision rewrite skipped (action denied)',
            'Disabled path completed (decision unavailable) · 820 ms',
        ]);
    });

    it('keeps the original text when the action broke after it started', () => {
        const [row] = decisionRows(play('action_failed'));
        expect(row.status).toBe('failed');
        expect(decisionOutcome(row).label).toBe('Failed');
        expect(outcomeSummary(row.request.outcomes[0])).toBe('Preserve original (action already started)');
        expect(actionSummary(row.actions[0])).toBe('Revision rewrite failed (action) · 820 ms');
    });
});

describe('a policy the scene cancelled', () => {
    it('does not call a cancelled policy a decision to do nothing', () => {
        const [row] = decisionRows(play('cancelled_after_answer'));
        expect(row.request.status).toBe('completed');
        expect(row.invocation.status).toBe('cancelled');
        expect(row.status).toBe('cancelled');
        expect(decisionOutcome(row).label).toBe('Cancelled');
        expect(decisionResult(row)).toBe('repeats · probability 0.74');
    });
});

describe('the outcome text is the template\'s own', () => {
    // A reason token is a template author's free choice, so these are the four
    // shapes the rule has to survive rather than records the framework emits.
    const cases = [
        [{ action: 'no_action', reason: 'below_threshold', details: { threshold: 0.8 } },
            'No action (below 0.80)'],
        [{ action: 'no_action', reason: 'repeats', details: { repeats: 0.74 } },
            'No action (repeats, repeats=0.74)'],
        [{ action: 'no_action', reason: 'manual threshold', details: { threshold: 0.8 } },
            'No action (manual threshold, threshold=0.80)'],
        [{ action: 'skip', reason: 'under configured_limit', details: { configured_limit: 12 } },
            'Skip (under configured limit, configured limit=12)'],
    ];
    for (const [outcome, text] of cases) {
        it(`reads ${text}`, () => {
            expect(outcomeSummary(outcome)).toBe(text);
        });
    }

    it('reads every probability with the same two decimals', () => {
        expect(answerSummary('repeats', { type: 'noul', p_true: 1 })).toBe('repeats · probability 1.00');
        expect(answerSummary('repeats', { type: 'noul', p_true: 0.9951 })).toBe('repeats · probability 1.00');
    });
});

describe('the number and the order come from the entries themselves', () => {
    it('numbers the rows from one and leaves a policy that has not asked out', () => {
        expect(decisionRows(play('below_threshold', { frames: 1 }))).toEqual([]);
        const [row] = decisionRows(play('below_threshold'));
        expect(row.num).toBe(1);
    });

    it('gives an invocation that asked nothing a row of its own', () => {
        const [row] = decisionRows(play('no_request'));
        expect(row.num).toBe(1);
        expect(decisionOutcome(row).label).toBe('No action');
        expect(decisionResult(row)).toBe('No questions submitted');
    });

    it('keeps the numbers it already gave when a snapshot repeats them', () => {
        const log = play('below_threshold');
        const before = decisionRows(log).map(row => [row.id, row.num]);
        applyDecisionFrame(log, scenarios.below_threshold.at(-1));
        expect(decisionRows(log).map(row => [row.id, row.num])).toEqual(before);
    });

    it('orders a request-less invocation among the requests by its own time', () => {
        const snapshot = scenarios.below_threshold.at(-1);
        const idle = {
            ...scenarios.no_request.at(-1).invocations[0],
            id: 'invocation-late',
            timestamp: '2026-09-21T09:59:00+00:00',
        };
        const log = createDecisionLog();
        applyDecisionFrame(log, {
            event: 'snapshot',
            requests: snapshot.requests,
            invocations: [...snapshot.invocations, idle],
        });
        expect(decisionRows(log).map(row => [row.id, row.num])).toEqual([
            ['invocation-late', 2],
            ['request-1', 1],
        ]);
    });

    it('forgets the number of an entry the backend removed', () => {
        const log = play('retention');
        expect(log.seen).not.toHaveProperty('request-1');
    });
});
